{
  "segment_function": "argument",
  "claims": [
    {
      "claim": "The main narrative of The Origins of Totalitarianism involves freeing oneself from processes that demolish the European nation-states, which maintained an artificial public realm for action.",
      "claim_type": "scholarly_interpretation",
      "supporting_excerpt": "the main narrative of The Origins of Totalitarianism is a getting free of processes which demolish the building of European nation-states erected in the former centuries. In the nation states, in the terms of the Arendtian political philosophy, an artifice of public realm as a stage for action had been created and maintained.",
      "support_kind": "direct",
      "confidence": 1
    },
    {
      "claim": "Totalitarianism represents the end-result of processes of re-naturalization, aiming to deprive human beings of their identity and change the human race into an animal species.",
      "claim_type": "author_position",
      "supporting_excerpt": "totalitarianism was the end-result of the processes of re-naturalization. For the introduction of this unprecedented political form an arsenal of new technologies was needed. They were, one the one hand, modern telecommunication technologies (press, radio, etc.) and, on the other hand, psycho-technologies (ideologies) and organizational–institutional technologies (bureaucracy). The first precondition of totalitarian regimes was the annihilation of human personality based on human spontaneity and invested with capability of free action (Arendt 1967: 455). The intention of totalitarianism was to deprive human beings from their identity and change human race into one of the animal species.",
      "support_kind": "direct",
      "confidence": 1
    }
  ],
  "definitions": [],
  "distinctions": [],
  "references_to_other_sections": [
    "The Origins of Totalitarianism",
    "The Human Condition"
  ],
  "unresolved_context": [],
  "must_not_be_lost": [
    "The transition from the narrative of cultural criticism to political philosophy via The Origins of Totalitarianism.",
    "Totalitarianism as the end-result of re-naturalization processes."
  ]
}

